/**
 * Story 336/337/340 — GS1 restricted-circulation ("in-store") barcodes.
 *
 * A 13-digit code starting with `2` is a retailer-local label, not a global product
 * identifier. Spike 336 decoded the layout from 202 Open Food Facts products:
 *
 *     2  352430  2  0383  3
 *     │  │       │  │     └─ EAN-13 check digit
 *     │  │       │  └─────── price in euro cents → €3.83
 *     │  │       └────────── price check digit
 *     │  └────────────────── item code (positions 1..6) — STABLE per product
 *     └───────────────────── restricted circulation
 *
 * The price moves with the weight of the package, so the full code differs on every
 * package and an exact lookup 404s forever. The item code does not: `2352430*` is AH
 * Biologische Kaas Jong Belegen across six observed codes and €3.59–€4.70, and the
 * pattern holds across AH, Jumbo, PLUS, Delhaize and Lidl.
 *
 * This module is the ONLY definition of "this is an in-store code". It lives in shared
 * because both the server's Open Food Facts fallback (337) and the food-item repository
 * that the PWA's offline router also runs (340) need the same answer.
 */

/** The retailer's per-product item code, or null when this is not an in-store barcode. */
export function inStoreItemCode(barcode: string): string | null {
    return /^2\d{12}$/.test(barcode) ? barcode.slice(1, 7) : null;
}
