export const JSON_HEADERS = { 'Content-Type': 'application/json' };

/**
 * Specialized error that when thrown from a repository, signals the route
 * to return a 404 instead of a 500.
 */
export class NotFoundError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'NotFoundError';
    }
}

/**
 * Repository-thrown error that maps to a 409. Used by story 075's write paths
 * when the on-disk file has uncommitted edits and the write would clobber.
 */
export class ConflictError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'ConflictError';
    }
}

/**
 * Repository-thrown error that maps to a 503. Used when persistent ID collisions
 * exhaust the create retry budget or the host's `git` invocation fails entirely.
 */
export class UnavailableError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'UnavailableError';
    }
}

/** Maps to 400 — used when a repository rejects validated input on deeper inspection. */
export class BadRequestError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'BadRequestError';
    }
}

/**
 * Story 241 — the GPU was occupied (Immich ML indexing held VRAM) and didn't
 * yield within the arbitration budget, so we declined to launch inference
 * rather than risk a CUDA OOM. Maps to 503; carries the machine-readable
 * `reason: 'gpu_contended'` so the PWA can render "GPU busy — Immich is
 * indexing" retry context instead of a generic failure.
 */
export const GPU_CONTENDED_REASON = 'gpu_contended';
export class GpuContendedError extends Error {
    readonly reason = GPU_CONTENDED_REASON;
    constructor(message: string) {
        super(message);
        this.name = 'GpuContendedError';
    }
}

/**
 * Story 386 — the model answered, but not with anything the parser can use (no
 * JSON, a required field missing, a value out of range). Maps to 422 with
 * `reason: 'unreadable'`: the PWA's label reader opens an empty draft on that
 * reason instead of offering a retry, so only a real reading failure may carry it
 * — a stopped or timed-out server is an `UnavailableError`.
 */
export const UNREADABLE_REASON = 'unreadable';
export class ModelOutputError extends Error {
    readonly reason = UNREADABLE_REASON;
    constructor(message: string) {
        super(message);
        this.name = 'ModelOutputError';
    }
}

/**
 * Story 386 — the one error-to-status mapping, used by `dispatchRoute`, the
 * server's terminal error handler and the offline router. A typed error maps by
 * its type; an error that already carries an HTTP error status keeps it
 * (Express's body parser marks a malformed body 400); anything else is a 500.
 */
export function statusForError(err: unknown): number {
    if (err instanceof BadRequestError) return 400;
    if (err instanceof NotFoundError) return 404;
    if (err instanceof ConflictError) return 409;
    if (err instanceof ModelOutputError) return 422;
    if (err instanceof UnavailableError || err instanceof GpuContendedError) return 503;
    if (err === null || typeof err !== 'object') return 500;
    const carried = (err as { status?: unknown }).status ?? (err as { statusCode?: unknown }).statusCode;
    if (typeof carried !== 'number' || !Number.isInteger(carried)) return 500;
    return carried >= 400 && carried <= 599 ? carried : 500;
}

/** The raw message as a JSON envelope, plus the machine-readable `reason` when the error has one. */
export function errorResponse(err: unknown): ApiResponse {
    const reason = err instanceof GpuContendedError || err instanceof ModelOutputError ? err.reason : undefined;
    return {
        status: statusForError(err),
        body: { error: err instanceof Error ? err.message : String(err), ...(reason && { reason }) },
        headers: JSON_HEADERS,
    };
}

// --- HTTP contract (framework-agnostic, section-agnostic) ---

/**
 * Response DTO returned by every shared route handler. The adapter
 * (Express + offline dispatcher) writes this to its own response shape.
 */
export interface ApiResponse {
    status: number;
    body?: unknown;
    headers?: Record<string, string>;
}

/**
 * Decoded request context passed to every shared route handler.
 * Path parameters are extracted by the adapter before the handler runs,
 * so handlers never parse paths.
 */
export interface RouteContext {
    params: Record<string, string>;
    query: URLSearchParams;
    body: unknown;
}

// --- Response helpers ---

export abstract class AbstractRouteResponses {
    protected ok(body: unknown): ApiResponse {
        return { status: 200, body, headers: JSON_HEADERS };
    }

    protected created(body: unknown): ApiResponse {
        return { status: 201, body, headers: JSON_HEADERS };
    }

    /** 202 — queued for a background run (async estimates, coaching generation). */
    protected accepted(body: unknown): ApiResponse {
        return { status: 202, body, headers: JSON_HEADERS };
    }

    protected noContent(): ApiResponse {
        return { status: 204 };
    }

    protected badRequest(error: string): ApiResponse {
        return { status: 400, body: { error }, headers: JSON_HEADERS };
    }

    protected notFound(error: string): ApiResponse {
        return { status: 404, body: { error }, headers: JSON_HEADERS };
    }

    protected conflict(error: string): ApiResponse {
        return { status: 409, body: { error }, headers: JSON_HEADERS };
    }

    protected unavailable(error: string): ApiResponse {
        return { status: 503, body: { error }, headers: JSON_HEADERS };
    }

    protected forbidden(error: string): ApiResponse {
        return { status: 403, body: { error }, headers: JSON_HEADERS };
    }
}
