const UUID_V7 = /^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

/** A lowercase RFC 9562 UUIDv7 — what a client may mint for a row it creates (story 370). */
export function isUuidV7(value: unknown): value is string {
    return typeof value === 'string' && UUID_V7.test(value);
}

let lastMs = -1;
let counter = 0;

/**
 * Generate a UUIDv7 (RFC 9562) — timestamp-sortable, and monotonic within this JS context (story 388).
 * `rand_a` is a 12-bit counter (RFC 9562 §6.2 method 1): seeded at random below 2048 on a new
 * millisecond, incremented within one, and on overflow — or a clock that stepped back — the
 * timestamp is carried forward instead. One implementation for server and phone: `globalThis.crypto`
 * has no `randomUUIDv7` on either, and `node:crypto`'s is not ordered within a millisecond.
 */
export function uuidv7(): string {
    const bytes = new Uint8Array(16);
    crypto.getRandomValues(bytes);

    const clock = Temporal.Now.instant().epochMilliseconds;
    if (clock > lastMs) {
        lastMs = clock;
        counter = ((bytes[6] << 8) | bytes[7]) & 0x7ff;
    } else if (++counter > 0xfff) {
        lastMs++;
        counter = 0;
    }
    const now = lastMs;
    bytes[6] = counter >> 8;
    bytes[7] = counter & 0xff;

    bytes[0] = (now / 2 ** 40) & 0xff;
    bytes[1] = (now / 2 ** 32) & 0xff;
    bytes[2] = (now / 2 ** 24) & 0xff;
    bytes[3] = (now / 2 ** 16) & 0xff;
    bytes[4] = (now / 2 ** 8) & 0xff;
    bytes[5] = now & 0xff;

    bytes[6] = (bytes[6] & 0x0f) | 0x70; // version 7
    bytes[8] = (bytes[8] & 0x3f) | 0x80; // variant 10

    const hex = Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('');
    return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}
