import { LINE_NUTRIENTS, type FoodItem, type LineNutrition } from '../types/health.js';

export type NutritionBasis = Pick<FoodItem, 'base_amount'> &
    Partial<Pick<FoodItem,
        'calories_per_base' | 'protein_g_per_base' | 'carbs_g_per_base' | 'fat_g_per_base'
        | 'fiber_g_per_base' | 'sugar_g_per_base' | 'sodium_mg_per_base'>>;

const NONE: LineNutrition = {
    calories: null, protein_g: null, carbs_g: null, fat_g: null, fiber_g: null, sugar_g: null, sodium_mg: null,
};

/**
 * Story 421 (418) — the one place a line's nutrition comes from: the food's per-base density
 * times `amount / base_amount`. A per-base value the food does not have stays `null` — unknown,
 * never 0 (story 368) — and so does everything when the basis or the amount is not a number.
 */
export function lineNutrition(food: NutritionBasis, amount: number): LineNutrition {
    const base = food.base_amount;
    if (!Number.isFinite(base) || base <= 0 || !Number.isFinite(amount)) return { ...NONE };
    const factor = amount / base;
    const scale = (per: number | null | undefined): number | null =>
        typeof per === 'number' && Number.isFinite(per) ? per * factor : null;
    return {
        calories: scale(food.calories_per_base),
        protein_g: scale(food.protein_g_per_base),
        carbs_g: scale(food.carbs_g_per_base),
        fat_g: scale(food.fat_g_per_base),
        fiber_g: scale(food.fiber_g_per_base),
        sugar_g: scale(food.sugar_g_per_base),
        sodium_mg: scale(food.sodium_mg_per_base),
    };
}

/**
 * A logged line's snapshot at a new amount (418 #4): scaled, never re-derived from the food, so
 * an override and a since-edited food both keep what was logged. Unknown stays unknown.
 */
export function rescaleNutrition(nutrition: LineNutrition, fromAmount: number, toAmount: number): LineNutrition {
    if (!Number.isFinite(fromAmount) || fromAmount <= 0 || !Number.isFinite(toAmount)) return { ...NONE };
    const factor = toAmount / fromAmount;
    const out = { ...NONE };
    for (const nutrient of LINE_NUTRIENTS) {
        const value = nutrition[nutrient];
        out[nutrient] = value === null ? null : value * factor;
    }
    return out;
}

/** Only the nutrients a line carries, from any row that has them as columns. */
export function pickNutrition(row: LineNutrition): LineNutrition {
    const out = { ...NONE };
    for (const nutrient of LINE_NUTRIENTS) out[nutrient] = row[nutrient];
    return out;
}
