import {
    LINE_NUTRIENTS,
    type DailyNutritionSummary,
    type FoodItem,
    type FrequentEntry,
    type LineInput,
    type LineNutrition,
    type Log,
    type LogLine,
    type LogUpdate,
    type LogWithLines,
    type Meal,
    type MealType,
    type NewLog,
} from '../types/health.js';
import type { DbDriver } from '../types/db.js';
import { NOOP_LOGGER, type RepoLogger } from '../types/logger.js';
import { uuidv7 } from '../utils/uuid.js';
import { resolveAppTimeZone } from '../utils/app-time.js';
import { BadRequestError, NotFoundError } from '../api/response-helpers.js';
import { lineNutrition, pickNutrition, rescaleNutrition } from '../utils/line-nutrition.js';
import { nowTimestamp, toTimestamp } from '../utils/timestamp.js';
import { createFoodItemRepository } from './food-items.repository.js';
import { foodItemColumns, FOOD_ITEM_COLUMNS } from './food-item-columns.js';
import { isImagePathReferenced } from './image-references.js';

const LOG_COLUMNS = 'id, date, meal_type, consumed_at, meal_id, name, created_at, updated_at';
const LINE_COLUMNS = `id, log_id, food_item_id, position, amount, unit, food_name, image_path,
    ${LINE_NUTRIENTS.join(', ')}, created_at, updated_at`;

// --- Story 276: slot-scoped frequent-items ranking ---

/** Logs older than this are ignored outright, so the scan stays bounded. */
const FREQUENT_WINDOW_DAYS = 365;

/**
 * A log loses half its weight every 30 days, so "what I eat for breakfast lately" beats "what I
 * ate a lot of last spring" without hard-cutting a still-occasional favourite. The clock is
 * SQLite's UTC `julianday('now')`: a relevance weight, not a local-day bucket.
 */
const FREQUENT_HALF_LIFE_DAYS = 30;

const frequentScoreSql = (dateColumn: string) =>
    `SUM(pow(0.5, (julianday('now') - julianday(${dateColumn})) / ${FREQUENT_HALF_LIFE_DAYS}.0))`;

const FREQUENT_MEAL_COLUMNS = 'm.id, m.name, m.notes, m.use_count, m.last_used_at, m.image_path, m.created_at, m.updated_at';

function frequentEntryName(entry: FrequentEntry): string {
    return entry.kind === 'food' ? entry.item.display_name : entry.meal.name;
}

// How many recent lines feed the default-serving recompute (story 117): reacts to a habit shift
// within a couple of weeks, dampens one outlier.
const DEFAULT_SERVING_WINDOW = 10;

function median(values: readonly number[]): number {
    const sorted = [...values].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    return sorted.length % 2 === 1 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

/**
 * `food_items.default_serving_amount` from the food's most recent lines (story 117): the median
 * of the last 10, last-used for ≤2. With no lines left the column is left alone. Ordered by
 * rowid, which only ever grows on insert — created_at ties within a millisecond.
 */
export async function recomputeDefaultServingAmount(driver: DbDriver, foodItemId: string): Promise<void> {
    const rows = await driver.query<{ amount: number }>(
        `SELECT amount FROM log_lines WHERE food_item_id = ? ORDER BY rowid DESC LIMIT ${DEFAULT_SERVING_WINDOW}`,
        foodItemId,
    );
    if (rows.length === 0) return;
    const next = rows.length <= 2 ? rows[0].amount : median(rows.map((r) => r.amount));
    await driver.execute(
        'UPDATE food_items SET default_serving_amount = ?, updated_at = ? WHERE id = ?',
        next, nowTimestamp(), foodItemId,
    );
}

/** `base` with each nutrient the override sets (null included — "unknown" is a value). */
function withOverride(base: LineNutrition, override: Partial<LineNutrition> | undefined): LineNutrition {
    const out = { ...base };
    for (const nutrient of LINE_NUTRIENTS) {
        const value = override?.[nutrient];
        if (value !== undefined) out[nutrient] = value;
    }
    return out;
}

/** A line as the repository will write it: the food it names and its final snapshot. */
interface ResolvedLine {
    food: FoodItem;
    amount: number;
    nutrition: LineNutrition;
}

export interface LogRepositoryOptions {
    log?: RepoLogger;
    /** Fired once a removed line's photo is referenced by nothing else (story 130). Best-effort. */
    onImageReleased?: (imagePath: string) => Promise<void> | void;
}

export function createLogRepository(driver: DbDriver, options: LogRepositoryOptions = {}) {
    const log = options.log ?? NOOP_LOGGER;
    const onImageReleased = options.onImageReleased;
    const foods = createFoodItemRepository(driver, { log });

    async function withLines(logs: Log[]): Promise<LogWithLines[]> {
        if (logs.length === 0) return [];
        const placeholders = logs.map(() => '?').join(',');
        const lines = await driver.query<LogLine>(
            `SELECT ${LINE_COLUMNS} FROM log_lines WHERE log_id IN (${placeholders}) ORDER BY position, rowid`,
            ...logs.map((l) => l.id),
        );
        const byLog = new Map<string, LogLine[]>();
        for (const line of lines) {
            const list = byLog.get(line.log_id) ?? [];
            list.push(line);
            byLog.set(line.log_id, list);
        }
        // Story 431: the cover of the meal a log came from — read here, so the day (server or
        // replica) gets it with the log, no fetch per meal.
        const mealIds = [...new Set(logs.map((l) => l.meal_id).filter((id): id is string => id !== null))];
        const covers = new Map<string, string | null>();
        if (mealIds.length > 0) {
            const rows = await driver.query<{ id: string; image_path: string | null }>(
                `SELECT id, image_path FROM meals WHERE id IN (${mealIds.map(() => '?').join(',')})`,
                ...mealIds,
            );
            for (const row of rows) covers.set(row.id, row.image_path);
        }
        return logs.map((l) => ({ ...l, meal_image_path: l.meal_id ? covers.get(l.meal_id) ?? null : null, lines: byLog.get(l.id) ?? [] }));
    }

    function assertOncePerFood(foodIds: Array<string | null>): void {
        const seen = new Set<string>();
        for (const id of foodIds) {
            if (id === null) continue;
            if (seen.has(id)) throw new BadRequestError(`Food item ${id} is listed more than once — a log lists each food once; change its amount instead`);
            seen.add(id);
        }
    }

    /** The food a new line names, creating an inline `new_food_item`. Call inside the transaction. */
    async function resolveNewLine(input: LineInput): Promise<ResolvedLine> {
        let food: FoodItem;
        if (input.new_food_item) {
            food = await foods.createOrReuse(input.new_food_item);
        } else if (input.food_item_id) {
            food = await driver.queryOne<FoodItem>(
                `SELECT ${FOOD_ITEM_COLUMNS} FROM food_items WHERE id = ?`,
                [input.food_item_id],
                { notFound: () => new NotFoundError(`Food item ${input.food_item_id} not found`) },
            );
        } else {
            throw new BadRequestError('A line needs a food_item_id or a new_food_item');
        }
        return { food, amount: input.amount, nutrition: withOverride(lineNutrition(food, input.amount), input.nutrition) };
    }

    async function insertLine(logId: string, position: number, line: ResolvedLine): Promise<void> {
        await driver.execute(
            `INSERT INTO log_lines (id, log_id, food_item_id, position, amount, unit, food_name, image_path, ${LINE_NUTRIENTS.join(', ')})
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ${LINE_NUTRIENTS.map(() => '?').join(', ')})`,
            uuidv7(), logId, line.food.id, position, line.amount, line.food.base_unit, line.food.display_name,
            line.food.image_path, ...LINE_NUTRIENTS.map((n) => line.nutrition[n]),
        );
    }

    async function updateLine(id: string, position: number, amount: number, nutrition: LineNutrition): Promise<void> {
        await driver.execute(
            `UPDATE log_lines SET position = ?, amount = ?, ${LINE_NUTRIENTS.map((n) => `${n} = ?`).join(', ')}, updated_at = ? WHERE id = ?`,
            position, amount, ...LINE_NUTRIENTS.map((n) => nutrition[n]), nowTimestamp(), id,
        );
    }

    async function inTransaction<T>(label: string, context: Record<string, unknown>, run: () => Promise<T>): Promise<T> {
        log.debug(`logs.${label}: BEGIN`, context);
        await driver.execute('BEGIN TRANSACTION');
        try {
            const result = await run();
            await driver.execute('COMMIT');
            log.debug(`logs.${label}: COMMIT`, context);
            return result;
        } catch (err) {
            await driver.execute('ROLLBACK');
            log.warn(`logs.${label}: ROLLBACK`, { ...context, error: err instanceof Error ? err.message : String(err) });
            throw err;
        }
    }

    async function recompute(foodIds: Iterable<string | null>): Promise<void> {
        for (const id of new Set(foodIds)) {
            if (id !== null) await recomputeDefaultServingAmount(driver, id);
        }
    }

    async function releaseImages(paths: Iterable<string | null>): Promise<void> {
        if (!onImageReleased) return;
        for (const path of new Set(paths)) {
            if (path && !(await isImagePathReferenced(driver, path))) {
                try { await onImageReleased(path); } catch { /* best-effort */ }
            }
        }
    }

    const repository = {
        async findById(id: string): Promise<LogWithLines | null> {
            log.debug('logs.findById', { id });
            const row = await driver.queryOne<Log>(`SELECT ${LOG_COLUMNS} FROM logs WHERE id = ?`, [id]);
            return row ? (await withLines([row]))[0] : null;
        },

        async getById(id: string): Promise<LogWithLines> {
            log.debug('logs.getById', { id });
            const row = await driver.queryOne<Log>(`SELECT ${LOG_COLUMNS} FROM logs WHERE id = ?`, [id], {
                notFound: () => new NotFoundError(`Log ${id} not found`),
            });
            return (await withLines([row]))[0];
        },

        async listByDate(date: string): Promise<LogWithLines[]> {
            log.debug('logs.listByDate', { date });
            return withLines(await driver.query<Log>(
                `SELECT ${LOG_COLUMNS} FROM logs WHERE date = ? ORDER BY meal_type, COALESCE(consumed_at, created_at), id`,
                date,
            ));
        },

        async listByDateRange(from: string, to: string): Promise<LogWithLines[]> {
            log.debug('logs.listByDateRange', { from, to });
            return withLines(await driver.query<Log>(
                `SELECT ${LOG_COLUMNS} FROM logs WHERE date >= ? AND date <= ? ORDER BY date DESC, meal_type, COALESCE(consumed_at, created_at), id`,
                from, to,
            ));
        },

        /** Per-day totals; `entry_count` counts lines. */
        async summary(from: string, to: string): Promise<DailyNutritionSummary[]> {
            log.debug('logs.summary', { from, to });
            return driver.query<DailyNutritionSummary>(
                `
                    SELECT l.date,
                           COALESCE(SUM(ll.calories), 0) AS total_calories,
                           COALESCE(SUM(ll.protein_g), 0) AS total_protein_g,
                           COALESCE(SUM(ll.carbs_g), 0) AS total_carbs_g,
                           COALESCE(SUM(ll.fat_g), 0) AS total_fat_g,
                           COALESCE(SUM(ll.fiber_g), 0) AS total_fiber_g,
                           COUNT(*) AS entry_count
                    FROM log_lines ll
                    JOIN logs l ON l.id = ll.log_id
                    WHERE l.date >= ? AND l.date <= ?
                    GROUP BY l.date
                    ORDER BY l.date DESC
                `,
                from, to,
            );
        },

        /**
         * Story 276 — the most-logged foods and meals for one slot, ranked together by a
         * recency-weighted count. Foods count the lines of logs not from a meal; meals count their
         * logs. Each half is ranked and limited in SQL and merged in memory — the top N of the
         * union is always inside the union of the two top-Ns.
         */
        async frequentByMealType(mealType: MealType, limit = 24): Promise<FrequentEntry[]> {
            log.debug('logs.frequentByMealType', { mealType, limit });
            const [foodRows, mealRows] = await Promise.all([
                driver.query<FoodItem & { score: number; last_at: string }>(
                    `
                        SELECT ${foodItemColumns('fi')},
                               ${frequentScoreSql('l.date')} AS score,
                               MAX(l.date) AS last_at
                        FROM log_lines ll
                        JOIN logs l ON l.id = ll.log_id
                        JOIN food_items fi ON fi.id = ll.food_item_id
                        WHERE l.meal_type = ?
                          AND l.meal_id IS NULL
                          AND l.date >= date('now', '-${FREQUENT_WINDOW_DAYS} days')
                          AND fi.archived_at IS NULL
                        GROUP BY ll.food_item_id
                        ORDER BY score DESC, last_at DESC, fi.display_name ASC
                        LIMIT ?
                    `,
                    mealType, limit,
                ),
                driver.query<Meal & { score: number; last_at: string }>(
                    `
                        SELECT ${FREQUENT_MEAL_COLUMNS},
                               ${frequentScoreSql('l.date')} AS score,
                               MAX(l.date) AS last_at
                        FROM logs l
                        JOIN meals m ON m.id = l.meal_id
                        WHERE l.meal_type = ?
                          AND l.date >= date('now', '-${FREQUENT_WINDOW_DAYS} days')
                        GROUP BY l.meal_id
                        ORDER BY score DESC, last_at DESC, m.name ASC
                        LIMIT ?
                    `,
                    mealType, limit,
                ),
            ]);
            const entries: FrequentEntry[] = [
                ...foodRows.map(({ score, last_at, ...item }) => ({ kind: 'food' as const, score, last_at, item })),
                ...mealRows.map(({ score, last_at, ...meal }) => ({ kind: 'meal' as const, score, last_at, meal })),
            ];
            return entries
                .sort((a, b) => b.score - a.score
                    || b.last_at.localeCompare(a.last_at)
                    || frequentEntryName(a).localeCompare(frequentEntryName(b)))
                .slice(0, limit);
        },

        /**
         * A log and its lines in one transaction (418 #3). A log from a meal takes the meal's name
         * unless one is given, and bumps the meal's use count; a log of foods bumps each food's.
         * An inline food is created with it, and goes with it if anything fails.
         */
        async create(payload: NewLog): Promise<LogWithLines> {
            if (payload.lines.length === 0) throw new BadRequestError('A log needs at least one line');
            const id = payload.id ?? uuidv7();
            await inTransaction('create', { id, date: payload.date, lines: payload.lines.length }, async () => {
                const lines: ResolvedLine[] = [];
                for (const input of payload.lines) lines.push(await resolveNewLine(input));
                assertOncePerFood(lines.map((l) => l.food.id));

                let name = payload.name ?? null;
                if (payload.meal_id) {
                    const meal = await driver.queryOne<Meal>('SELECT name FROM meals WHERE id = ?', [payload.meal_id], {
                        notFound: () => new NotFoundError(`Meal ${payload.meal_id} not found`),
                    });
                    name ??= meal.name;
                }
                await driver.execute(
                    'INSERT INTO logs (id, date, meal_type, consumed_at, meal_id, name) VALUES (?, ?, ?, ?, ?, ?)',
                    id, payload.date, payload.meal_type, payload.consumed_at ?? null, payload.meal_id ?? null, name,
                );
                for (const [position, line] of lines.entries()) await insertLine(id, position, line);

                const now = nowTimestamp();
                if (payload.meal_id) {
                    await driver.execute('UPDATE meals SET use_count = use_count + 1, last_used_at = ?, updated_at = ? WHERE id = ?', now, now, payload.meal_id);
                } else {
                    for (const line of lines) {
                        await driver.execute('UPDATE food_items SET use_count = use_count + 1, last_used_at = ?, updated_at = ? WHERE id = ?', now, now, line.food.id);
                    }
                }
                await recompute(lines.map((l) => l.food.id));
            });
            return repository.getById(id);
        },

        /**
         * Date, slot, time or name — one row (418 #2). A date move keeps a stamp's wall-clock time
         * in `time_zone` (story 260), so a 19:00 dinner stays a 19:00 dinner across DST.
         */
        async update(id: string, updates: LogUpdate): Promise<LogWithLines> {
            const existing = await repository.getById(id);
            const fields: string[] = [];
            const values: unknown[] = [];
            for (const field of ['date', 'meal_type', 'consumed_at', 'name'] as const) {
                if (updates[field] !== undefined) {
                    fields.push(`${field} = ?`);
                    values.push(updates[field]);
                }
            }
            if (updates.date !== undefined && updates.consumed_at === undefined && existing.consumed_at !== null) {
                const zone = resolveAppTimeZone(updates.time_zone);
                const wallClock = Temporal.Instant.from(existing.consumed_at).toZonedDateTimeISO(zone).toPlainTime();
                fields.push('consumed_at = ?');
                values.push(toTimestamp(Temporal.PlainDate.from(updates.date).toZonedDateTime({ timeZone: zone, plainTime: wallClock }).toInstant()));
            }
            if (fields.length === 0) return existing;
            log.debug('logs.update', { id, fields: Object.keys(updates) });
            await driver.execute(`UPDATE logs SET ${fields.join(', ')}, updated_at = ? WHERE id = ?`, ...values, nowTimestamp(), id);
            return repository.getById(id);
        },

        /**
         * The complete, final list of lines (story 311's semantics). A line sent with its `id` is
         * kept: a new amount rescales its snapshot and `nutrition` overrides it (418 #4). A line
         * without one is new; a line not sent is removed.
         */
        async replaceLines(id: string, inputs: LineInput[]): Promise<LogWithLines> {
            if (inputs.length === 0) throw new BadRequestError('A log needs at least one line — delete the log instead');
            const existing = await repository.getById(id);
            const current = new Map(existing.lines.map((l) => [l.id, l]));
            for (const input of inputs) {
                if (input.id !== undefined && !current.has(input.id)) {
                    throw new BadRequestError(`Line ${input.id} is not a line of log ${id}`);
                }
            }
            const keptIds = new Set(inputs.flatMap((i) => (i.id === undefined ? [] : [i.id])));
            const removed = existing.lines.filter((l) => !keptIds.has(l.id));

            await inTransaction('replaceLines', { id, lines: inputs.length }, async () => {
                // Removed first, so a food re-added under a new line does not meet its old one.
                for (const line of removed) await driver.execute('DELETE FROM log_lines WHERE id = ?', line.id);
                const added: ResolvedLine[] = [];
                const foodIds: Array<string | null> = [];
                for (const [position, input] of inputs.entries()) {
                    const line = input.id === undefined ? undefined : current.get(input.id);
                    if (line) {
                        const nutrition = withOverride(rescaleNutrition(pickNutrition(line), line.amount, input.amount), input.nutrition);
                        await updateLine(line.id, position, input.amount, nutrition);
                        foodIds.push(line.food_item_id);
                    } else {
                        const resolved = await resolveNewLine(input);
                        await insertLine(id, position, resolved);
                        added.push(resolved);
                        foodIds.push(resolved.food.id);
                    }
                }
                assertOncePerFood(foodIds);
                await driver.execute('UPDATE logs SET updated_at = ? WHERE id = ?', nowTimestamp(), id);
                await recompute([...foodIds, ...removed.map((l) => l.food_item_id)]);
            });
            await releaseImages(removed.map((l) => l.image_path));
            return repository.getById(id);
        },

        /** Every amount and snapshot × `factor`; relative, so ×1.5 twice is ×2.25. Unknown stays unknown. */
        async scale(id: string, factor: number): Promise<LogWithLines> {
            if (!Number.isFinite(factor) || factor <= 0) throw new BadRequestError('factor must be a positive number');
            const existing = await repository.getById(id);
            await inTransaction('scale', { id, factor }, async () => {
                await driver.execute(
                    `UPDATE log_lines SET amount = amount * ?, ${LINE_NUTRIENTS.map((n) => `${n} = ${n} * ?`).join(', ')}, updated_at = ? WHERE log_id = ?`,
                    factor, ...LINE_NUTRIENTS.map(() => factor), nowTimestamp(), id,
                );
                await driver.execute('UPDATE logs SET updated_at = ? WHERE id = ?', nowTimestamp(), id);
                await recompute(existing.lines.map((l) => l.food_item_id));
            });
            return repository.getById(id);
        },

        async delete(id: string): Promise<boolean> {
            const existing = await repository.findById(id);
            if (!existing) return false;
            await inTransaction('delete', { id }, async () => {
                await driver.execute('DELETE FROM logs WHERE id = ?', id);
                await recompute(existing.lines.map((l) => l.food_item_id));
            });
            await releaseImages(existing.lines.map((l) => l.image_path));
            return true;
        },
    };

    return repository;
}

export type LogRepository = ReturnType<typeof createLogRepository>;
