// --- Health Section Types ---

import type { OptionalNullables } from './db.js';

export const MEAL_TYPES = ['Breakfast', 'Lunch', 'Dinner', 'Snacks'] as const;
export type MealType = typeof MEAL_TYPES[number];

/**
 * Closed set of `activities.type` values. Story 146 locks this list with a
 * `CHECK` constraint at the DB layer and at the Strava ingestion edge.
 * Manual-entry UI dropdowns iterate this array; ingestion guards against
 * Strava sport_types that snake-case to anything outside it (logged + skipped).
 *
 * `Activity.type` remains typed as `string` for read-side back-compat — the
 * CHECK constraint and ingestion guard are the runtime enforcers. Code that
 * wants to be precise (e.g. dropdown bindings, switch statements) can use the
 * derived `ActivityType` union.
 */
export const ACTIVITY_TYPES = [
    'running', 'cycling', 'walking', 'hiking', 'swimming',
    'tennis', 'ice_skate', 'alpine_ski',
    'hiit', 'weight_training', 'workout',
] as const;
export type ActivityType = typeof ACTIVITY_TYPES[number];

/**
 * `health_connect_*` values encode ingest path + writer (story 250): all arrive via the on-device
 * Health Connect bridge. Non-`manual` sources are read-only in the API.
 *
 * Since story 303 only `health_connect_android_fitness` is still produced — Google Fit is the one
 * writer the bridge sync ingests. The other two stay in the union (and in the `activities.source`
 * CHECK) because rows carrying them are real history on the server.
 */
export const ACTIVITY_SOURCES = [
    'manual',
    'strava',
    'calendar',
    /** Health Connect writer `com.strava`. No longer ingested (story 303); 8 rows still carry it. */
    'health_connect_strava',
    'health_connect_android_fitness',
    /** Health Connect writer `com.fitbit.FitbitMobile`, the Google Health app (story 298). No longer ingested (story 303). */
    'health_connect_google_health',
] as const;
export type ActivitySource = typeof ACTIVITY_SOURCES[number];

export interface Activity {
    id: string;
    type: string;
    source: ActivitySource;
    title: string;
    /** Nullable columns: an edit sends `null` to clear one (story 371). */
    description: string | null;
    date: string;
    duration_minutes: number | null;
    calories_burned: number | null;
    external_id: string | null;
    metadata: string | null;
    created_at: string;
    updated_at: string;
}

export type NewActivity = OptionalNullables<Omit<Activity, 'id' | 'created_at' | 'updated_at'>>;

/**
 * Read shape of `GET /activities` (story 259 follow-up): `distance_m` is
 * joined from `cardio_details` so burn estimates can pace-band
 * walking/running/cycling without a per-activity fetch. Not a column on
 * `activities` — write paths keep using `PATCH /cardio-details/:activityId`.
 *
 * `moving_time_minutes` rides the same join (story 312), so the step estimate
 * and the honest pace are both derivable from one query. The name is kept as
 * the read shape's rather than renamed to `ActivityWithCardio`: every caller
 * spells it, and the join is still one table.
 */
export type ActivityWithDistance = Activity & { distance_m: number | null; moving_time_minutes: number | null };

/**
 * Where a food item's numbers came from.
 *
 * Story 338 added `label_photo`: macros read off a photographed nutrition
 * table. It is deliberately NOT `ai_estimate` — that is a model guessing what a
 * generic food contains (story 316 measured it at ~17–21% median kcal error),
 * while this is a model transcribing a measured table printed on the product.
 * It is deliberately not `manual` either: a hand-typed row was checked by a
 * human character by character, and a transcription was not, so collapsing the
 * two would make the reads impossible to find again and audit.
 */
export type NutritionSource = 'manual' | 'openfoodfacts' | 'ai_estimate' | 'mfp_import' | 'label_photo';

export interface DailyNutritionSummary {
    date: string;
    total_calories: number;
    total_protein_g: number;
    total_carbs_g: number;
    total_fat_g: number;
    total_fiber_g: number;
    entry_count: number;
}

/**
 * One representative weight per app-local date (the daily average of all
 * weigh-ins that day). The single source of truth for "weight per day" shared
 * by the coaching prompt (story 172) and the trend chart (story 171).
 */
export interface DailyWeightSummary {
    date: string;
    weight_kg: number;
}

/**
 * Header stats for the health timeline. `streak_days` is the number of
 * consecutive days ending today (or yesterday if today has no activity yet)
 * on which the user logged at least one meaningful activity, capped at 365.
 * Trivial walks (see `utils/meaningful-activity.ts`, story 252) do not
 * sustain the streak.
 * `avg_calories_7d` is the mean of `total_calories` across the last seven
 * days where the user actually logged consumption (zero-calorie days are
 * excluded so a single bad day doesn't drag the average to zero).
 */
export interface HealthStats {
    streak_days: number;
    avg_calories_7d: number;
}

/**
 * Story 258 — user targets behind the v3 timeline/day-detail visuals, stored
 * as synced `settings` rows (same mechanism as `app.timezone`) so the PWA and
 * future server readers agree. Values are persisted as decimal strings.
 */
export const HEALTH_CALORIE_BUDGET_KEY = 'health.calorie_budget';
export const HEALTH_PROTEIN_TARGET_KEY = 'health.protein_target';
export const HEALTH_STEP_GOAL_KEY = 'health.step_goal';

export interface HealthTargets {
    calorie_budget_kcal: number;
    protein_target_g: number;
    step_goal: number;
}

export const DEFAULT_HEALTH_TARGETS: HealthTargets = {
    calorie_budget_kcal: 2500,
    protein_target_g: 150,
    step_goal: 10000,
};

/**
 * AI coaching advice (story 074; multi-entry per date as of story 174).
 * `status` walks pending → done | failed. Each generation run appends its own
 * entry (latest `created_at` wins for display); older entries for the same
 * date are retained. `pushed_at` marks the entry whose morning push fired, so
 * the notify task pushes at most once per date.
 */
export const COACHING_ADVICE_STATUSES = ['pending', 'done', 'failed'] as const;
export type CoachingAdviceStatus = typeof COACHING_ADVICE_STATUSES[number];

export interface CoachingAdvice {
    /** Surrogate UUIDv7 PK (story 174) — many entries may share a `date`. */
    id: string;
    date: string;
    status: CoachingAdviceStatus;
    advice: string | null;
    /**
     * One-line ≤80-char actionable nudge (story 261), emitted by the model
     * before the briefing and stripped out of `advice`. Null when the model
     * omitted it or emitted it malformed, or on pre-261 rows — surfaces fall
     * back to first-line truncation of `advice`.
     */
    headline: string | null;
    model: string | null;
    error: string | null;
    /** When the entry was enqueued — the prompt's generation vantage (story 174). */
    created_at: string;
    generated_at: string | null;
    /** Set when the advice is hand-edited (story 175); null otherwise. */
    updated_at: string | null;
    pushed_at: string | null;
}

/**
 * AI nutrition estimate. Field names align with the `food_items` table
 * (`*_per_base` against `base_amount = 100` / `base_unit = 'g'`) so the
 * server can persist the estimate without a conversion step. The model
 * also reports `default_serving_amount` (the meal's total weight in grams)
 * and a numeric `confidence_score` so AI metadata maps 1:1 onto
 * `ai_estimations.confidence_score`.
 */
export interface NutritionEstimate {
    canonical_name: string;
    display_name: string;
    base_amount: number;
    base_unit: FoodBaseUnit;
    default_serving_amount: number;
    calories_per_base: number;
    protein_g_per_base: number;
    carbs_g_per_base: number;
    fat_g_per_base: number;
    /** Story 396: absent when the model gave no readable value — never a made-up 0. */
    fiber_g_per_base?: number;
    sugar_g_per_base?: number;
    sodium_mg_per_base?: number;
    confidence_score: number;
    notes: string;
}

export interface Per100gNutrition {
    calories: number;
    protein_g: number;
    carbs_g: number;
    fat_g: number;
    fiber_g?: number;
    sugar_g?: number;
    sodium_mg?: number;
}

export const FOOD_BASE_UNITS = ['g', 'ml', 'piece'] as const;
export type FoodBaseUnit = typeof FOOD_BASE_UNITS[number];

/**
 * Library entry for any loggable food. Nutrient densities are stored once
 * per row as `*_per_base` values relative to `base_amount` in `base_unit`
 * (e.g. base_amount=100 base_unit='g' for "per 100g"). The optional
 * `serving_label` + `serving_quantity` pair is a UI-only display affordance
 * — backend math always converts to grams before computing macros.
 */
export interface FoodItem {
    id: string;
    canonical_name: string;
    display_name: string;
    brand: string | null;
    barcode: string | null;
    source: NutritionSource;
    source_ref: string | null;
    base_amount: number;
    base_unit: FoodBaseUnit;
    default_serving_amount: number | null;
    serving_label: string | null;
    serving_quantity: number | null;
    calories_per_base: number | null;
    protein_g_per_base: number | null;
    carbs_g_per_base: number | null;
    fat_g_per_base: number | null;
    fiber_g_per_base: number | null;
    sugar_g_per_base: number | null;
    sodium_mg_per_base: number | null;
    use_count: number;
    last_used_at: string;
    raw_json: string | null;
    /**
     * Directory key under FILES_DIR/images/ (e.g. 'images/food/<uuidv7>'). The
     * UI appends `/display.jpg` (rendered, 1280px progressive JPEG) or
     * `/original.<ext>` (archive). Independent of `ai_estimations.image_path`
     * — see design_log.md #125.
     */
    image_path: string | null;
    /**
     * ISO timestamp set when the row is archived. Non-NULL = hidden from
     * search/list endpoints; `GET /food-items/:id` still returns the row and
     * every reference stays (418 #5). Story 120.
     */
    archived_at: string | null;
    /** Story 435 — an AI-made food the user said "Looks right" to; it leaves "To check". */
    reviewed_at: string | null;
    created_at: string;
    updated_at: string;
}

/**
 * A barcode lookup's answer. Story 369: `matched_by: 'item_code'` marks a food found only through
 * an in-store label's item code — another package of the same code, possibly from another store,
 * so the screen asks rather than assumes.
 */
export type FoodItemBarcodeMatch = FoodItem & { matched_by?: 'item_code' };

/**
 * Story 423 — the food library's lists: every live food; the AI-made ones not yet checked (story
 * 435 — a label read is real numbers); the archived ones.
 */
export const FOOD_LIST_FILTERS = ['all', 'to_check', 'archived'] as const;
export type FoodListFilter = typeof FOOD_LIST_FILTERS[number];

/**
 * Story 435 — what replacing an AI-made food would move, for the confirm to name. It does not
 * depend on the replacement, so the confirm comes before an Open Food Facts product or a label
 * read is added to the library.
 */
export interface FoodReplacementImpact {
    meals: number;
    log_lines: number;
}

/** Story 423 — a barcode that resolves to a food: its own (`food_items.barcode`) or one it was seen wearing (story 340). */
export interface FoodItemBarcode {
    barcode: string;
    kind: 'own' | 'learned';
    item_code: string | null;
}

export type NewFoodItem = OptionalNullables<Omit<FoodItem, 'id' | 'created_at' | 'updated_at' | 'last_used_at' | 'use_count'>> & {
    last_used_at?: string;
    use_count?: number;
};

/**
 * 1-1 subtype of `FoodItem` for rows whose `source = 'ai_estimate'`. Holds
 * the prompt, model, image reference, and confidence so the food library
 * itself stays clean and a future RAG store can scan AI metadata directly.
 */
export interface AiEstimation {
    food_item_id: string;
    model_name: string;
    prompt_used: string;
    image_path: string | null;
    confidence_score: number | null;
    raw_response: string | null;
    created_at: string;
}

export type NewAiEstimation = OptionalNullables<Omit<AiEstimation, 'created_at'>>;

/**
 * Story 205 — 1-1 embedding row per food item (server-only table; the PWA
 * never reads it). `embedded_text` is the LLM-canonicalized English ingredient
 * name the vector was computed from; `model` invalidates vectors on a model
 * switch. Design log #179.
 */
export interface FoodItemEmbedding {
    food_item_id: string;
    model: string;
    vector: Uint8Array;
    embedded_text: string;
    /** The food item's name composite at canonicalization time — rename staleness marker (migration 023). */
    source_text: string;
    created_at: string;
    updated_at: string;
}

export type NewFoodItemEmbedding = Omit<FoodItemEmbedding, 'created_at' | 'updated_at'>;

/**
 * Story 447 — a food an estimate cannot match by similarity yet: its English name is still to be
 * translated, which waits for the chat model to be up (`GET /food-items/embedding-waiting`).
 */
export interface WaitingFood {
    id: string;
    display_name: string;
    brand: string | null;
}

export const LINE_NUTRIENTS = ['calories', 'protein_g', 'carbs_g', 'fat_g', 'fiber_g', 'sugar_g', 'sodium_mg'] as const;
export type LineNutrient = typeof LINE_NUTRIENTS[number];

/** A line's nutrition. `null` is unknown, never zero (story 368). */
export type LineNutrition = Record<LineNutrient, number | null>;

/**
 * Story 421 (418 #2) — one logged food or meal. Date, slot, eaten-at, meal and a name snapshot
 * live once, here; what was eaten is its `lines`. A single food logged is a one-line log (#3).
 */
export interface Log {
    id: string;
    date: string;
    meal_type: MealType;
    /**
     * When it was actually eaten (ISO instant, story 260). Null when never stamped; rendering
     * projects through the app timezone. Never re-derives the slot: `meal_type` stays the key.
     */
    consumed_at: string | null;
    /** The meal it was logged from; null for a food or an ad-hoc list, or once the meal is deleted. */
    meal_id: string | null;
    /** The meal's name when logged, so it survives the meal (418 #5); null means "name by its line". */
    name: string | null;
    created_at: string;
    updated_at: string;
}

/**
 * What was eaten, snapshotted when logged (418 #4): nutrition, name, unit and photo. Editing or
 * deleting the food later never rewrites it; changing `amount` rescales the snapshot.
 */
export interface LogLine extends LineNutrition {
    id: string;
    log_id: string;
    /** Null once the food is deleted (418 #5); the snapshot still reads. */
    food_item_id: string | null;
    position: number;
    amount: number;
    unit: FoodBaseUnit;
    food_name: string;
    image_path: string | null;
    created_at: string;
    updated_at: string;
}

export interface LogWithLines extends Log {
    /** Story 431: the cover of the meal this log came from; null without one (or once it is deleted). */
    meal_image_path?: string | null;
    lines: LogLine[];
}

/**
 * One line as a client sends it (418 #1, #7): a library food or an inline `new_food_item`, and
 * an amount in the food's base unit. On a log, `id` names a line already there (kept, rescaled),
 * and `nutrition` overrides what the food would give (story 368).
 */
export interface LineInput {
    id?: string;
    food_item_id?: string;
    new_food_item?: NewFoodItem;
    amount: number;
    nutrition?: Partial<LineNutrition>;
}

/** `POST /logs`. `lines` carries final amounts — a scale is the client's pre-fill (418 #6). */
export interface NewLog {
    /** A client-minted uuidv7, so an offline log is the row it becomes. */
    id?: string;
    date: string;
    meal_type: MealType;
    consumed_at?: string | null;
    meal_id?: string | null;
    name?: string | null;
    lines: LineInput[];
}

/** `PATCH /logs/:id`. A date move keeps a stamp's wall-clock time in `time_zone` (story 260). */
export interface LogUpdate {
    date?: string;
    meal_type?: MealType;
    consumed_at?: string | null;
    name?: string | null;
    time_zone?: string;
}

/**
 * Body-weight measurement (story 170). Structural sibling of ConsumptionEntry:
 * a scalar value bucketed by app-local `date`, many rows allowed per day.
 * Body weight only for v1 — body composition is a future InBody import.
 */
export interface WeightEntry {
    id: string;
    date: string;
    weight_kg: number;
    /** `null` clears it on an edit (story 371). */
    notes: string | null;
    created_at: string;
    updated_at: string;
}

export type NewWeightEntry = OptionalNullables<Omit<WeightEntry, 'id' | 'created_at' | 'updated_at'>>;

/**
 * Story 251 — one row per app-local day of aggregated step count, ingested
 * from Health Connect via the bridge (which aggregates per local day with
 * HC's aggregate API). Re-syncs upsert by `date`, overwriting the total.
 */
export interface DailySteps {
    date: string;
    steps: number;
    source: string;
    created_at: string;
    updated_at: string;
}

export type NewDailySteps = Omit<DailySteps, 'created_at' | 'updated_at'>;

/**
 * Reusable meal template — created here so the schema is complete; behavior
 * (search integration, log-time expansion, scaling, editor UI) lives in
 * story 077.
 */
export interface Meal {
    id: string;
    name: string;
    /** `null` clears it on an edit (story 371). */
    notes: string | null;
    use_count: number;
    last_used_at: string | null;
    /**
     * Directory key under FILES_DIR/images/meal/ (e.g. 'images/meal/<uuidv7>').
     * UI appends `/display.jpg`. Optional cover photo — null means no banner,
     * and `null` on an edit removes it (story 371).
     */
    image_path: string | null;
    created_at: string;
    updated_at: string;
}

export interface MealIngredient {
    id: string;
    meal_id: string;
    food_item_id: string;
    amount: number;
    position: number;
}

/** Ingredient row joined with its `food_items` row, returned from `meals.getById`. */
export interface MealIngredientWithFoodItem extends MealIngredient {
    food_item: FoodItem;
}

/** Meal joined with its (positionally-ordered) ingredients + each ingredient's food item. */
export interface MealWithIngredients extends Meal {
    ingredients: MealIngredientWithFoodItem[];
}

/**
 * Story 276 — one tile in the food-search screen's frequent-items grid.
 *
 * Foods and meal templates are ranked against each other in a single list, so
 * the payload is a tagged union rather than two parallel arrays. `score` is the
 * recency-weighted log count that produced the ordering (see
 * `consumption.frequentByMealType`); it is returned for debuggability and
 * ordering stability, not for display.
 */
export type FrequentEntry =
    | { kind: 'food'; score: number; last_at: string; item: FoodItem }
    | { kind: 'meal'; score: number; last_at: string; meal: Meal };

/**
 * Create / replace payload for a meal template (`POST /meals`, `PUT /meals/:id`). `ingredients`
 * is the full list — `PUT` replaces the meal as a whole. `position` is implicit (array order).
 * An ingredient may be an inline `new_food_item`, created with the meal (418 #7). Its amounts are
 * the usual portion: there is no template scale (418 #6).
 */
export interface NewMealWithIngredients {
    /** On create only: a client-minted uuidv7 (story 370). */
    id?: string;
    name: string;
    /** `null` clears it (story 371). */
    notes?: string | null;
    /** Optional cover-photo directory key (e.g. 'images/meal/<uuidv7>'); `null` removes it. */
    image_path?: string | null;
    ingredients: Array<Pick<LineInput, 'food_item_id' | 'new_food_item' | 'amount'>>;
}

// --- Story 205/206: ingredient resolution & meal estimation ---

export type ResolutionProvenance = 'matched_library' | 'matched_off' | 'generated';
export type ResolutionTier = 'exact' | 'similarity' | 'judge' | 'off' | 'generated';

/**
 * Story 319 — the bound row is one of several active rows sharing this
 * canonical name, and they disagree about calories. Tie-breaking on
 * consumption count has no opinion about which row is *correct*, and both
 * candidate replacements were measured and refuted
 * (`docs/spikes/319-evidence`), so the binding stands and the disagreement is
 * reported instead of resolved silently. Absent when the siblings agree.
 */
export interface ResolutionDivergence {
    /** Active rows sharing the canonical name, the bound one included. */
    sibling_count: number;
    /** kcal per 100 g/ml across the comparable siblings, rounded to 0.1 — the bound row is somewhere in this range. */
    kcal_min: number;
    kcal_max: number;
}

/**
 * Story 205 — how one ingredient was bound to a food item. Story 423 (418 #7): an ingredient
 * nothing in the library is binds to a *proposed* food (an Open Food Facts product or an AI
 * estimate) that no row exists for yet — `food_item_id` null, `proposed` the food a save creates.
 */
export interface IngredientResolution {
    food_item_id: string | null;
    /** The food a save would create; set exactly when `food_item_id` is null. */
    proposed?: NewFoodItem;
    provenance: ResolutionProvenance;
    /** Similarity of the bound match; 1 for exact, null for OFF/generated rows. */
    similarity: number | null;
    tier: ResolutionTier;
    /** True when the food is new — proposed, and created only when the draft is saved (423). */
    created: boolean;
    /** Story 319 — set only when same-name siblings disagree on kcal; see `ResolutionDivergence`. */
    divergence?: ResolutionDivergence;
}

/** Story 206 — one decomposed ingredient with its binding and meal amount. */
export interface ResolvedMealIngredient extends IngredientResolution {
    /** The canonical English ingredient name the decomposition emitted. */
    canonical_name: string;
    /** Amount for this meal, in the bound food item's base_unit. */
    amount: number;
}

/**
 * Story 206 — response of POST /food-items/estimate. Story 423 (418 #7): the same draft the async
 * job holds — nothing is written until it is saved through `/logs`, `/meals` or `/food-items`.
 */
export type MealEstimateResult = EstimateJobResult;

// --- Story 338: a photographed nutrition table becomes a draft food item ---

/**
 * Which column of the nutrition table the macros were read from.
 *
 * A Dutch label routinely prints both "per 100 g" and "per portie"; reading the
 * wrong one and storing it against `base_amount: 100` is story 192's 20,500 kcal
 * Chocomel. So the model must SAY which column it used, and the value decides
 * the row's `base_amount` rather than being assumed.
 */
export const LABEL_BASES = ['per_100g', 'per_serving'] as const;
export type LabelBasis = typeof LABEL_BASES[number];

/**
 * The macro fields a label read can come back missing. A blurred or cropped
 * table is the normal case, not an exception, so the read names what it could
 * not get instead of silently writing a zero — a 0 g fat row and an unread fat
 * row look identical once saved.
 */
export const LABEL_READ_FIELDS = [
    'calories_per_base',
    'protein_g_per_base',
    'carbs_g_per_base',
    'fat_g_per_base',
    'fiber_g_per_base',
    'sugar_g_per_base',
    'sodium_mg_per_base',
] as const;
export type LabelReadField = typeof LABEL_READ_FIELDS[number];

/**
 * Story 338 — response of POST /food-items/read-label.
 *
 * A **proposal**, never a saved row: the route reads the label and returns; the
 * review surface is what turns it into a `food_items` row. The nutrition table
 * is the part most likely to be misread, so nothing here is trusted enough to
 * persist unseen.
 */
export interface LabelReadResult {
    /** The proposed row, `source: 'label_photo'`. Not persisted by the read route. */
    draft: NewFoodItem;
    /** Which column `draft`'s `*_per_base` values came from. */
    basis: LabelBasis;
    /**
     * Macro fields the model could not read. They are `undefined` on `draft`
     * (not 0), and the review surface leaves them blank and says so.
     */
    unread: LabelReadField[];
    confidence_score: number;
    /** The model's own note — which column it used, what was unreadable. */
    notes: string;
}

// --- Story 211: async (submit-and-walk-away) estimation ---

/** Lifecycle of a background estimate job. */
export type EstimateJobStatus = 'queued' | 'done' | 'failed';

/**
 * Story 294 — how the user dispositioned a finished estimate. Separate from
 * `status`, which describes the *pipeline* and stays `'done'` either way.
 * `'discarded'` is re-acceptable on purpose: "I threw this away and changed my
 * mind" is a real action, and gating the accept route on `'accepted'` rather
 * than on `reviewed_at` is what leaves that door open.
 */
export const ESTIMATE_JOB_DISPOSITIONS = ['accepted', 'discarded'] as const;
export type EstimateJobDisposition = typeof ESTIMATE_JOB_DISPOSITIONS[number];

/**
 * The assembled result the async pipeline produces for review. Mirrors the
 * synchronous `MealEstimateResult`, except a multi-ingredient meal is NOT yet
 * persisted: the job carries the would-be meal's name + resolved ingredients
 * (each with its bound `food_item`, so the review view can render names/macros
 * with no extra fetch) until the user accepts. A single-ingredient result
 * binds a food item exactly like the sync flow (story 219).
 */
export type EstimateJobResult =
    | {
        kind: 'meal';
        meal_name: string;
        ingredients: Array<ResolvedMealIngredient & { food_item: DraftFood }>;
        confidence_score?: number;
        notes?: string;
    }
    | {
        kind: 'food_item';
        food_item: DraftFood;
        resolution: ResolvedMealIngredient;
    };

/**
 * Story 423 — a draft's food: a library row, or the food a save creates (418 #7). A job stored
 * before 423 holds only rows, which this still reads.
 */
export type DraftFood = FoodItem | NewFoodItem;

export function isLibraryFood(food: DraftFood): food is FoodItem {
    return 'id' in food && typeof food.id === 'string';
}

/**
 * A background AI-estimation job. Server-only (NOT in `TRACKED_TABLES`): the
 * PWA reaches it through the API and has no offline replica — the pipeline
 * needs the GPU, which only exists server-side. The meal/log is created from
 * `result` only when the user accepts; `reviewed_at` marks a job the user has
 * dispositioned, and `disposition` says which way (story 294).
 */
export interface EstimateJob {
    id: string;
    status: EstimateJobStatus;
    description: string | null;
    image_path: string | null;
    /** Local-day + meal slot the result logs into on accept. */
    date: string;
    meal_type: MealType;
    result: EstimateJobResult | null;
    /** Raw error when status === 'failed' (fail-loud — surfaced in the UI). */
    error: string | null;
    reviewed_at: string | null;
    /**
     * Story 294 — what the job became. `reviewed_at` alone could not say, which
     * is why the accept route could only guard on `status` and a second accept
     * created a second meal. `null` on a job nobody has dispositioned yet — and
     * also on the rows that predate this column, where the outcome is genuinely
     * unknown and was deliberately not guessed at (see migration 033).
     */
    disposition: EstimateJobDisposition | null;
    /** The meal an accept produced, when it produced one. */
    logged_meal_id: string | null;
    created_at: string;
    updated_at: string;
    /**
     * Story 310 — an existing meal with this result's exact ingredient set.
     * **Not a column**: the single-job GET computes it at read time, so it
     * cannot go stale against a meal that has since been renamed or deleted,
     * and no migration is needed. Absent unless the job is `done`, still
     * undispositioned, and produced a meal.
     */
    duplicate_of?: DuplicateMealRef;
}

/** Story 310 — the existing meal an estimate duplicates, as the review screen needs it. */
export interface DuplicateMealRef {
    id: string;
    name: string;
    /** How often the existing template has been logged — the "is this the one I actually use?" signal. */
    use_count: number;
}

/**
 * Story 310 — what an accept should do when the estimate duplicates an existing
 * meal's ingredient set. Omitted means `create_new`: the choice is opt-in, so an
 * accept that predates the review-screen UI behaves exactly as it always did.
 */
export const ON_DUPLICATE_ACTIONS = ['log_new_amounts', 'update_template', 'create_new'] as const;
export type OnDuplicateAction = typeof ON_DUPLICATE_ACTIONS[number];

// --- Workout logging (story 140 / spike 138) ---

export const EXERCISE_CATEGORIES = [
    'squat', 'hinge', 'push', 'pull', 'lunge', 'core', 'olympic', 'carry', 'bodyweight', 'other',
] as const;
export type ExerciseCategory = typeof EXERCISE_CATEGORIES[number];

export const EXERCISE_DEFAULT_UNITS = ['kg', 'lb', 'bodyweight'] as const;
export type ExerciseDefaultUnit = typeof EXERCISE_DEFAULT_UNITS[number];

export const WORKOUT_BLOCK_KINDS = ['interval', 'rest', 'note'] as const;
export type WorkoutBlockKind = typeof WORKOUT_BLOCK_KINDS[number];

/**
 * Library entry for any loggable exercise (loaded barbell lift, bodyweight
 * movement, timed isometric). Analogous to `FoodItem`. `tracks_*` flags
 * disambiguate "what does logging this even mean" — `tracks_reps=0` +
 * `tracks_duration=1` describes a plank, which has no reps and no weight.
 */
export interface Exercise {
    id: string;
    canonical_name: string;
    display_name: string;
    category: ExerciseCategory;
    default_unit: ExerciseDefaultUnit;
    tracks_reps: number;
    tracks_weight: number;
    tracks_duration: number;
    /**
     * `1` when the movement is done one limb at a time (single-arm row,
     * Bulgarian split squat), `0` when both limbs work together. Story 288 —
     * a one-arm 32 kg and a two-arm 32 kg are different lifts, so the
     * per-exercise MAX is unreadable without it.
     */
    is_unilateral: number;
    notes: string | null;
    use_count: number;
    last_used_at: string | null;
    archived_at: string | null;
    created_at: string;
    updated_at: string;
}

export type NewExercise = OptionalNullables<Omit<
    Exercise,
    'id' | 'created_at' | 'updated_at' | 'use_count' | 'last_used_at' | 'is_unilateral'
>> & {
    use_count?: number;
    last_used_at?: string;
    /** Optional on create — the column defaults to 0 (both limbs). */
    is_unilateral?: number;
};

/**
 * 1:1 optional subtype of `activities` carrying Strava session-level metrics.
 * A row exists when Strava (or manual entry) supplied at least one measured
 * metric. Individual columns are nullable — NULL means "not measured," never
 * "measured as zero." Spike 138 §4.2.
 */
export interface CardioDetails {
    activity_id: string;
    distance_m: number | null;
    elevation_gain_m: number | null;
    avg_speed_mps: number | null;
    /**
     * How long `distance_m` took, when that is not the whole session (story
     * 312) — a treadmill block inside a gym class. Null means "not
     * stated", and `avg_speed_mps` is then computed against the activity's own
     * `duration_minutes`, as it always was. Minutes, matching
     * `activities.duration_minutes`.
     */
    moving_time_minutes: number | null;
    avg_hr: number | null;
    max_hr: number | null;
    created_at: string;
    updated_at: string;
}

export type NewCardioDetails = OptionalNullables<Omit<CardioDetails, 'created_at' | 'updated_at'>>;

/**
 * 1:1 optional subtype of `activities` carrying intra-session structure
 * (strength sets and/or interval blocks). `activity_id` is both PK and FK —
 * same pattern as `ai_estimations.food_item_id`. Spike 138 §4.3.
 */
export interface WorkoutSession {
    activity_id: string;
    source_template_id: string | null;
    notes: string | null;
    created_at: string;
    updated_at: string;
}

export type NewWorkoutSession = OptionalNullables<Omit<WorkoutSession, 'created_at' | 'updated_at'>>;

/**
 * One row per actual set performed. `position` is the global order within the
 * session (squat1, squat2, …, bench1, bench2); `set_index` is the 1..N within
 * the same exercise (squat is 1-3, bench is 1-2). Spike 138 §4.4.
 */
export interface StrengthSet {
    id: string;
    session_id: string;
    position: number;
    exercise_id: string;
    set_index: number;
    reps: number | null;
    weight_kg: number | null;
    rpe: number | null;
    rest_s: number | null;
    notes: string | null;
}

export type NewStrengthSet = OptionalNullables<Omit<StrengthSet, 'id'>>;

/**
 * Patch payload for one set (story 290). **`null` clears the column, `undefined`
 * leaves it alone** — the distinction `updateStrengthSet` has always relied on,
 * and one `Partial<NewStrengthSet>` cannot express, because `undefined` is
 * dropped by `JSON.stringify` and so can never mean "clear" over the wire.
 *
 * Written out field by field rather than mapped over `NewStrengthSet`: a mapped
 * type would make `position` and `set_index` nullable too, and those back NOT
 * NULL columns — a set can be reordered but never un-ordered.
 */
export interface StrengthSetUpdate {
    reps?: number | null;
    weight_kg?: number | null;
    rpe?: number | null;
    rest_s?: number | null;
    notes?: string | null;
    position?: number;
    set_index?: number;
}

/**
 * The heaviest set ever logged for one exercise, plus the date it was set —
 * the "what am I chasing" line above an exercise card (story 288). A record
 * is only legible with its date, which is why this is its own shape rather
 * than a bare `StrengthSet`: the date lives on `activities`, not on the set.
 */
export interface ExerciseMaxSet {
    exercise_id: string;
    session_id: string;
    /** Local date (`YYYY-MM-DD`) of the activity the set belongs to. */
    date: string;
    reps: number | null;
    weight_kg: number | null;
}

/**
 * Intervals / rest / notes attached to a workout session. Flat — no recursive
 * `parent_block_id`. The TRIB3 "5 min run → 1 min speed 6 / 1 min speed 7"
 * case becomes sibling rows sharing `parent_label='5 min run'`. Spike 138 §4.5.
 */
export interface WorkoutBlock {
    id: string;
    session_id: string;
    position: number;
    /** The optional columns are nullable; an edit sends `null` to clear one (story 371). */
    parent_label: string | null;
    kind: WorkoutBlockKind;
    modality: string | null;
    duration_s: number | null;
    distance_m: number | null;
    intensity: string | null;
    avg_hr: number | null;
    notes: string | null;
}

export type NewWorkoutBlock = OptionalNullables<Omit<WorkoutBlock, 'id'>>;

/** Session joined with its strength sets and workout blocks — the read shape returned by `workouts.getById`. */
export interface WorkoutSessionWithDetail extends WorkoutSession {
    strength_sets: StrengthSet[];
    workout_blocks: WorkoutBlock[];
}

/**
 * Reusable workout prescription. Logging a template expands it into a session
 * in one transaction (mirrors `meals.logMeal`, design_log #117). Editing the
 * template never rewrites history. Spike 138 §4.6.
 */
export interface WorkoutTemplate {
    id: string;
    name: string;
    notes: string | null;
    use_count: number;
    last_used_at: string | null;
    archived_at: string | null;
    created_at: string;
    updated_at: string;
}

export interface TemplateStrengthSet {
    id: string;
    template_id: string;
    position: number;
    exercise_id: string;
    target_set_count: number;
    target_reps: number | null;
    target_weight_kg: number | null;
    target_rpe: number | null;
    target_rest_s: number | null;
    notes: string | null;
}

export type NewTemplateStrengthSet = OptionalNullables<Omit<TemplateStrengthSet, 'id'>>;

export interface TemplateBlock {
    id: string;
    template_id: string;
    position: number;
    parent_label: string | null;
    kind: WorkoutBlockKind;
    modality: string | null;
    target_duration_s: number | null;
    target_distance_m: number | null;
    target_intensity: string | null;
    notes: string | null;
}

export type NewTemplateBlock = OptionalNullables<Omit<TemplateBlock, 'id'>>;

/** Template joined with its (positionally-ordered) target sets and blocks. */
export interface WorkoutTemplateWithBlocks extends WorkoutTemplate {
    strength_sets: TemplateStrengthSet[];
    blocks: TemplateBlock[];
}

/**
 * Create/update payload for a workout template. `strength_sets` and `blocks` are
 * the full positional child lists — the repository replaces existing rows on
 * update (same pattern as meal_ingredients).
 */
export interface NewWorkoutTemplateWithBlocks {
    name: string;
    notes?: string;
    strength_sets: Array<Omit<NewTemplateStrengthSet, 'template_id' | 'position'>>;
    blocks?: Array<Omit<NewTemplateBlock, 'template_id' | 'position'>>;
}

/** Payload for `workouts.logTemplate(template_id, payload)`. */
export interface WorkoutLogPayload {
    date: string;
    title?: string;
}

/** Result of `workouts.logTemplate` — the created activity id and the populated session. */
export interface WorkoutLogResult {
    activity_id: string;
    session: WorkoutSessionWithDetail;
}
