/**
 * Story 389 — the one stored-timestamp form: a UTC instant to the millisecond,
 * `2026-10-22T10:00:00.000Z`. The precision is fixed because `*_at` columns are
 * compared and ordered as text: Temporal's default `toString()` prints as many
 * digits as the clock has, and `…:50Z` sorts after `…:50.5Z`. It is exactly the
 * string `SQL_NOW_TIMESTAMP` writes, so a column DEFAULT and a bound value agree.
 */
export function toTimestamp(instant: Temporal.Instant): string {
    return instant.toString({ smallestUnit: 'millisecond' });
}

export function nowTimestamp(): string {
    return toTimestamp(Temporal.Now.instant());
}

/** The column-DEFAULT spelling of `nowTimestamp()` — DDL cannot bind a parameter. */
export const SQL_NOW_TIMESTAMP = "strftime('%Y-%m-%dT%H:%M:%fZ', 'now')";
