/**
 * Story 390 — the coaching settings rows the PWA writes and the overnight run reads (stories 074,
 * 153). The server mirrored the default independently.
 */
export const COACHING_GOALS_KEY = 'coaching.goals';
export const COACHING_TONE_KEY = 'coaching.tone';
export const COACHING_WORKOUT_WINDOW_KEY = 'coaching.workout_window';

export interface WorkoutWindow {
    start: string; // HH:MM
    end: string; // HH:MM
}

export const DEFAULT_WORKOUT_WINDOW: Readonly<WorkoutWindow> = Object.freeze({ start: '06:00', end: '22:00' });

/** The stored window, or the default for a missing or malformed row. */
export function parseWorkoutWindow(raw: string | null): WorkoutWindow {
    if (!raw) return { ...DEFAULT_WORKOUT_WINDOW };
    try {
        const parsed = JSON.parse(raw) as { start?: unknown; end?: unknown };
        if (typeof parsed.start === 'string' && typeof parsed.end === 'string') {
            return { start: parsed.start, end: parsed.end };
        }
    } catch {
        // fall through to default on malformed JSON
    }
    return { ...DEFAULT_WORKOUT_WINDOW };
}
